const initialMarkup = "\n<div id=\"login\" class=\"login\"><div class=\"login-card\"><img class=\"login-emblem\" alt=\"Emblema Corpo de Bombeiros\" src=\"data:image/png;base64,\"><h1>Monitor Legislativo</h1><p>Corpo de Bombeiros</p><label>Senha<input id=\"pwd\" type=\"password\"></label><button class=\"primary login-btn\" onclick=\"entrar()\">Entrar</button><div id=\"loginErr\" class=\"error\"></div></div></div>\n<div id=\"app\" class=\"app hidden\"><aside><div class=\"brand\"><img class=\"brand-emblem\" alt=\"Emblema Corpo de Bombeiros\" src=\"data:image/png;base64,\"><div><b>Monitor Legislativo</b><small>Corpo de Bombeiros</small></div></div>\n<button class=\"nav active\" data-page=\"painel\">Painel</button><button class=\"nav\" data-page=\"pesquisa\">Pesquisa diária</button><button class=\"nav\" data-page=\"proposituras\">Proposituras</button><button class=\"nav\" data-page=\"alteracoes\">Alterações</button><button class=\"nav\" data-page=\"avaliacao\">Avaliação de proposituras</button><button class=\"nav\" data-page=\"relatorios\">Relatórios</button>\n<div class=\"aside-foot\"><button class=\"settings-btn\" onclick=\"configuracoes()\" title=\"Configurações\">⚙ <span>Configurações</span></button><button onclick=\"sair()\">Sair</button></div></aside><main><header><div><h1 id=\"title\">Painel</h1><p id=\"subtitle\">Acompanhamento diário das proposições legislativas</p></div></header><div id=\"page\"></div></main></div><div id=\"toast\"></div>\n<div id=\"global-loading\" class=\"global-loading\" aria-live=\"polite\" aria-hidden=\"true\"><span class=\"loading-spinner\"></span><span id=\"global-loading-text\">Processando...</span></div>\n";
const legacyScript = "\nvar token=localStorage.getItem('ml_token')||'',current=null,dash=null,viewCache={},loadingCount=0,automaticSearchCache={},__autoRows={};\nfunction loadingLabel(fn){fn=String(fn||'');if(fn==='login')return 'Entrando no sistema...';if(fn==='getDashboard')return 'Carregando painel...';if(/proposit/i.test(fn))return 'Carregando proposituras...';if(/alterac/i.test(fn))return 'Carregando alterações...';if(/candidat|avali/i.test(fn))return 'Carregando avaliação...';if(/relatorio/i.test(fn))return 'Carregando relatórios...';if(/verificar|reverificar|regime/i.test(fn))return 'Consultando fonte oficial...';if(/salvar|registrar|adicionar|atualizar|alterar|concluir|aprovar|ignorar|reabrir/i.test(fn))return 'Salvando alterações...';return 'Processando...';}\nfunction showLoading(msg){loadingCount++;var el=document.getElementById('global-loading'),txt=document.getElementById('global-loading-text');if(txt)txt.textContent=msg||'Processando...';if(el){el.classList.add('show');el.setAttribute('aria-hidden','false');}}\nfunction hideLoading(){loadingCount=Math.max(0,loadingCount-1);if(loadingCount===0){var el=document.getElementById('global-loading');if(el){el.classList.remove('show');el.setAttribute('aria-hidden','true');}}}\nfunction api(fn,args){args=args||[];showLoading(loadingLabel(fn));return fetch('/api/rpc',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({fn:fn,args:args})}).then(function(res){return res.json().then(function(r){if(!res.ok||r.ok===false){var msg=String(r&&r.message?r.message:'Erro na operação.');if(/sess[aã]o expirada/i.test(msg)){localStorage.removeItem('ml_token');token='';mostrarLogin('Sua sessão expirou. Entre novamente.');}throw new Error(msg);}return r.data!==undefined?r.data:r;});}).catch(function(e){throw e;}).finally(function(){hideLoading();});}\nasync function cached(key,fn,args,ttl){ttl=ttl||30000;var c=viewCache[key];if(c&&Date.now()-c.t<ttl)return c.v;var v=await api(fn,args);viewCache[key]={t:Date.now(),v:v};return v;}\nfunction invalidate(){for(var i=0;i<arguments.length;i++)delete viewCache[arguments[i]];}\nfunction mostrarLogin(msg){document.getElementById('app').classList.add('hidden');document.getElementById('login').classList.remove('hidden');document.getElementById('loginErr').textContent=msg||'';}\nasync function entrar(){try{var r=await api('login',[document.getElementById('pwd').value]);if(!r.ok)return document.getElementById('loginErr').textContent=r.message;token=r.token;localStorage.setItem('ml_token',token);await mostrar();}catch(e){document.getElementById('loginErr').textContent=e.message;}}\nfunction sair(){localStorage.removeItem('ml_token');token='';current=null;dash=null;viewCache={};loadingCount=0;hideLoading();var p=document.getElementById('pwd');if(p)p.value='';mostrarLogin('');setTimeout(function(){if(p)p.focus();},50);}\nasync function mostrar(){document.querySelectorAll('.nav').forEach(function(b){b.onclick=function(){document.querySelectorAll('.nav').forEach(function(x){x.classList.remove('active')});b.classList.add('active');route(b.dataset.page);}});try{dash=await api('getDashboard',[token]);document.getElementById('login').classList.add('hidden');document.getElementById('app').classList.remove('hidden');renderPainel();}catch(e){mostrarLogin(e.message);}}\nfunction route(p){if(p==='painel')painel();if(p==='pesquisa')pesquisaDiaria();if(p==='proposituras')proposituras();if(p==='alteracoes')alteracoes();if(p==='avaliacao')avaliacao();if(p==='relatorios')relatorios();}\nfunction setTitle(a,b){document.getElementById('title').textContent=a;document.getElementById('subtitle').textContent=b;}function page(){return document.getElementById('page')}function stat(l,v){return '<div class=\"stat\"><small>'+l+'</small><b>'+v+'</b></div>'}\nasync function painel(){setTitle('Painel','Acompanhamento diário das proposições legislativas');dash=await api('getDashboard',[token]);renderPainel();}\nfunction renderPainel(){var h=dash.hoje,a=dash.emAndamento;page().innerHTML='<div class=\"today '+(h?'ok':'')+'\"><span class=\"eyebrow\">VERIFICAÇÃO DE HOJE</span><h3>'+(h?'Relatório concluído':'Ainda não realizada')+'</h3><p>'+(h?(esc(h.responsavel)+' · '+esc(h.emissao||h.fimTecnico)):'Nenhum relatório diário foi concluído hoje.')+'</p></div>'+ (a&&!h?'<div class=\"active-session\"><div><b>Verificação diária em andamento</b><p>'+esc(a.responsavel)+' iniciou a verificação de hoje.</p></div><button class=\"primary\" onclick=\"continuarSessaoAtual()\">Continuar verificação</button></div>':'') +'<div class=\"stats\">'+stat('Proposituras',dash.total)+stat('Câmara',dash.fontes&&dash.fontes['Câmara']||0)+stat('ALESP',dash.fontes&&dash.fontes['ALESP']||0)+stat('Senado',dash.fontes&&dash.fontes['Senado']||0)+'</div><div class=\"panel\"><h2>Realizar verificação diária</h2><p class=\"intro\">Primeiro o sistema verifica automaticamente as proposituras monitoradas. A pesquisa de novas matérias só é liberada quando as três casas forem concluídas.</p><div class=\"field-row\"><label>Responsável pela consulta<input id=\"responsavel\" placeholder=\"Nome do responsável\"></label><button id=\"start\" class=\"primary\" onclick=\"iniciar()\" '+(a&&!h?'disabled':'')+'>Iniciar verificação diária</button></div><div id=\"steps\" class=\"steps hidden\"></div><div id=\"after\" class=\"after-check hidden\"></div></div>';}\nasync function continuarSessaoAtual(){var a=dash.emAndamento;if(!a)return;current={id:a.id,responsavel:a.responsavel};try{var v=await api('getVerificacaoAtual',[token,a.id]);if(v.status==='CONCLUÍDA'){await renderBuscaGuiada(a.id);return;}current.fontes=(v.detalhes&&v.detalhes.resultados)||[];setTitle('Painel','Verificação automática com pendências');page().innerHTML='<div class=\"panel\"><h2>Verificação automática incompleta</h2><p class=\"intro\">Ainda há uma ou mais casas com pendências. Tente novamente antes da pesquisa guiada.</p><div id=\"steps\" class=\"steps\">'+current.fontes.map(function(r){var id=r.fonte==='Câmara'?'cam':r.fonte==='Senado'?'sen':'ale';var ok=Number(r.erros||0)===0&&Number(r.verificado||0)===Number(r.previsto||0);return '<div class=\"step '+(ok?'done':'warn')+'\" id=\"'+id+'\"><span class=\"bullet\">'+(ok?'✓':'!')+'</span><div><b>'+esc(r.fonte)+' — proposituras monitoradas</b><small>'+(ok?'Concluído':resumoPendenciaFonte(r))+'</small></div></div>'+(r.detalhes&&r.detalhes.length?'<div class=\"details\">'+esc(r.detalhes.slice(0,5).join('\\n'))+'</div>':'')}).join('')+'</div><div id=\"after\" class=\"after-check\"></div></div>';renderResultadoAutomatico(false);}catch(e){toast(e.message)}}\nasync function iniciar(){var nome=document.getElementById('responsavel').value.trim();if(!nome)return toast('Informe o responsável.');var btn=document.getElementById('start');btn.disabled=true;var etapas=[['cam','Câmara — proposituras monitoradas','verificarCamara','Câmara'],['sen','Senado — proposituras monitoradas','verificarSenado','Senado'],['ale','ALESP — proposituras monitoradas','verificarAlesp','ALESP']];var s=document.getElementById('steps');s.classList.remove('hidden');s.innerHTML=etapas.map(function(e){return '<div class=\"step\" id=\"'+e[0]+'\"><span class=\"bullet\">○</span><div><b>'+e[1]+'</b><small>Aguardando</small></div></div>'}).join('');try{var ini=await api('iniciarVerificacao',[token,nome]);current={id:ini.verificationId,responsavel:nome,fontes:[]};for(var i=0;i<etapas.length;i++){var e=etapas[i];step(e[0],'run','Executando...',[]);var r;try{r=await api(e[2],[token,current.id])}catch(err){r={erros:1,detalhes:[err.message],fonte:e[3],previsto:0,verificado:0}}current.fontes.push(r);step(e[0],Number(r.erros||0)?'warn':'done',Number(r.erros||0)?resumoPendenciaFonte(r):'Concluído',r.detalhes||[])}await finalizarEtapaAutomatica();}catch(e){toast(e.message);btn.disabled=false;}}\nfunction resumoPendenciaFonte(r){if(Number(r.verificado||0)===0&&Number(r.previsto||0)>1)return 'Consulta não concluída';return Number(r.erros||0)+' pendência(s)';}\nasync function finalizarEtapaAutomatica(){var totalPrev=current.fontes.reduce(function(a,b){return a+Number(b.previsto||0)},0),totalVer=current.fontes.reduce(function(a,b){return a+Number(b.verificado||0)},0),alt=current.fontes.reduce(function(a,b){return a+Number(b.alteracoes||0)},0),completa=current.fontes.length===3&&current.fontes.every(function(x){return Number(x.erros||0)===0&&Number(x.verificado||0)===Number(x.previsto||0)});var resumo={completa:completa,totalPrevisto:totalPrev,totalVerificado:totalVer,alteracoes:alt,candidatas:0,palavras:(dash.palavras||[]).length,buscas:0,fontes:'Câmara, Senado, ALESP',resultados:current.fontes};await api('concluirVerificacaoTecnica',[token,current.id,resumo]);renderResultadoAutomatico(completa);var btn=document.getElementById('start');if(btn){btn.textContent=completa?'Verificação automática concluída':'Verificação automática incompleta';btn.disabled=true}toast(completa?'Verificação automática concluída.':'A verificação automática possui pendências.');}\nfunction renderResultadoAutomatico(completa){var h=document.getElementById('after');if(!h)return;h.classList.remove('hidden');if(completa){h.innerHTML='<p>As três casas foram verificadas. Você pode seguir para a pesquisa de novas matérias.</p><button class=\"primary\" onclick=\"abrirBuscaGuiada()\">Continuar para pesquisa guiada</button>';}else{var falhas=(current.fontes||[]).filter(function(x){return Number(x.erros||0)>0||Number(x.verificado||0)!==Number(x.previsto||0)});h.innerHTML='<div><b>Verificação incompleta</b><p>Resolva as pendências abaixo antes de continuar.</p></div><div id=\"retry-status\"></div><div class=\"retry-source-actions\">'+falhas.map(function(x){return '<button class=\"secondary retry-source-btn\" onclick=\"tentarFonteNovamente(\\''+escJs(x.fonte)+'\\',this)\">Tentar novamente — '+esc(x.fonte)+'</button>'}).join('')+'</div>';}}\nasync function tentarFonteNovamente(fonte,botao){\n var original=botao?botao.textContent:'';\n try{\n  document.querySelectorAll('.retry-source-btn').forEach(function(b){b.disabled=true});\n  if(botao){botao.textContent='Consultando '+fonte+'...';botao.classList.add('is-loading')}\n  var st=document.getElementById('retry-status');\n  if(st)st.innerHTML='<div class=\"retry-running\"><span class=\"mini-spinner\"></span><div><b>Realizando nova consulta à '+esc(fonte)+'...</b><small>Aguarde o retorno da fonte oficial.</small></div></div>';\n  var resumo=await api('reverificarFonte',[token,current.id,fonte]);\n  current.fontes=resumo.resultados||current.fontes;\n  var ids={'Câmara':'cam','Senado':'sen','ALESP':'ale'},r=current.fontes.find(function(x){return x.fonte===fonte});\n  if(r)step(ids[fonte],Number(r.erros||0)?'warn':'done',Number(r.erros||0)?resumoPendenciaFonte(r):'Concluído',r.detalhes||[]);\n  renderResultadoAutomatico(!!resumo.completa);\n  var btn=document.getElementById('start');\n  if(btn)btn.textContent=resumo.completa?'Verificação automática concluída':'Verificação automática incompleta';\n  toast(resumo.completa?'As três casas foram concluídas.':'Nova consulta à '+fonte+' finalizada.');\n }catch(e){\n  toast(e.message);\n  var st2=document.getElementById('retry-status');\n  if(st2)st2.innerHTML='<div class=\"retry-error\">A nova consulta não foi concluída. Você pode tentar novamente.</div>';\n }finally{\n  if(botao){botao.textContent=original||('Tentar novamente — '+fonte);botao.classList.remove('is-loading')}\n  document.querySelectorAll('.retry-source-btn').forEach(function(b){b.disabled=false});\n }\n}\nfunction step(id,cls,txt,det){var e=document.getElementById(id);e.className='step '+cls;e.querySelector('.bullet').textContent=cls==='done'?'✓':cls==='warn'?'!':'●';e.querySelector('small').textContent=txt;if(det&&det.length){var d=document.createElement('div');d.className='details';d.textContent=det.slice(0,5).join('\\n');e.parentNode.insertBefore(d,e.nextSibling)}}\nasync function abrirBuscaGuiada(){await renderBuscaGuiada(current.id)}\nasync function renderBuscaGuiada(id){\n setTitle('Pesquisa guiada','Pesquisa automática de novas proposituras nas fontes oficiais');\n try{\n  var d=await api('getBuscaGuiada',[token,id]);\n  var fontesComResultados=await Promise.all(d.fontes.map(async function(f){\n    try{\n      return Object.assign({},f,{resultados:await api('getResultadosPesquisaAutomatica',[token,id,f.fonte])});\n    }catch(_){\n      return Object.assign({},f,{resultados:[]});\n    }\n  }));\n  var done=fontesComResultados.filter(function(f){return f.registro&&f.registro.status==='Concluída'}).length;\n  page().innerHTML='<div class=\"panel guided-research\"><div class=\"guided-title\"><div><h2>Pesquisa de novas proposituras</h2><p class=\"intro\">O sistema consulta automaticamente as fontes oficiais pelos Termos de apoio. Revise os resultados encontrados e envie somente as matérias pertinentes para avaliação.</p></div><span class=\"research-progress\">'+done+' de 3 concluídas</span></div>'+\n   '<details class=\"terms terms-managed\" open><summary>Termos de apoio</summary><div class=\"term-chips\">'+d.palavras.map(function(w){return '<span class=\"term-chip\">'+esc(w.termo||w)+' <button title=\"Remover termo\" onclick=\"removerTermoApoio(\\''+escJs(w.id||'')+'\\')\">×</button></span>'}).join('')+'</div><div class=\"term-add\"><input id=\"guidedNewTerm\" placeholder=\"Adicionar novo termo de apoio\" onkeydown=\"if(event.key===\\'Enter\\')adicionarTermoApoio()\"><button class=\"secondary\" onclick=\"adicionarTermoApoio()\">+ Incluir termo</button></div><p class=\"terms-help\">Os termos ativos serão usados nas próximas pesquisas automáticas.</p></details>'+\n   '<div class=\"guided-source-grid\">'+fontesComResultados.map(function(f){return renderFonteGuiada(f)}).join('')+'</div>'+\n   '<div class=\"standalone-register guided-register\"><div class=\"section-title-row\"><div><h3>Encontrou uma propositura relevante?</h3><p>Os resultados automáticos ficam aqui para análise. Você decide quais vão para <b>Avaliação de proposituras</b>.</p></div><button class=\"secondary\" onclick=\"abrirCadastroCandidata()\">+ Registrar manualmente</button></div><div id=\"candidateForm\"></div></div><div id=\"reviewArea\"></div></div>';\n  if(done===3)mostrarRevisao();\n }catch(e){toast(e.message)}\n}\nfunction renderFonteGuiada(f){\n var r=f.registro||{},done=r.status==='Concluída',results=f.resultados||[];\n return '<div class=\"guide-card guided-source '+(done?'source-complete':'')+'\"><div class=\"guide-top\"><div><div class=\"source-title-line\"><h3>'+esc(f.fonte)+'</h3>'+(done?'<span class=\"source-status done\">Concluída</span>':'<span class=\"source-status pending\">Pendente</span>')+'</div><p>Pesquisa automática na fonte oficial</p></div><div class=\"source-action-row\"><button class=\"primary\" onclick=\"pesquisarAutomaticamente(\\''+escJs(f.fonte)+'\\',this)\">'+(results.length?'Pesquisar novamente':'Pesquisar automaticamente')+'</button><a class=\"secondary link-btn\" target=\"_blank\" href=\"'+esc(f.link)+'\">Abrir fonte oficial</a></div></div>'+\n   '<div class=\"automatic-summary\">'+(results.length?'<b>'+results.length+' resultado(s) listado(s)</b><span>Revise as matérias antes de enviá-las para avaliação.</span>':'<span>Nenhuma pesquisa automática executada nesta sessão.</span>')+'</div>'+\n   '<div class=\"'<div class=\"automatic-search-help\"><b>Como interpretar a correspondência:</b> o termo indica a busca que trouxe a matéria. Ele pode não aparecer literalmente na ementa ou nos metadados exibidos, porque a fonte oficial pode pesquisar outros campos.</div>'+\n   '<div class=\"automatic-results\">'+renderResultadosAutomaticos(results,'guided_'+safeId(fonteSafe(f.fonte)))+'</div></div>';\n}\nfunction categoriaAutoLabel(x){\n return String(x.categoriaTipo||'Não identificado');\n}\nfunction renderAutomaticRows(rows,filterKey){\n var statusFilter=(document.getElementById(filterKey+'-status')||{}).value||'todos';\n var categoryFilter=(document.getElementById(filterKey+'-category')||{}).value||'todos';\n var typeFilter=(document.getElementById(filterKey+'-type')||{}).value||'todos';\n var filtered=rows.filter(function(x){\n   var st=String(x.status||'Nova');\n   var cat=categoriaAutoLabel(x);\n   var type=String(x.tipo||'').toUpperCase();\n   return (statusFilter==='todos'||st===statusFilter) &&\n          (categoryFilter==='todos'||cat===categoryFilter) &&\n          (typeFilter==='todos'||type===typeFilter);\n });\n var summary=document.getElementById(filterKey+'-summary');\n if(summary)summary.textContent=filtered.length+' de '+rows.length+' resultado(s)';\n var list=document.getElementById(filterKey+'-list');\n if(!list)return;\n list.innerHTML=filtered.length?filtered.map(function(x){\n   var st=String(x.status||'Nova'),blocked=st==='Já monitorada'||st==='Em avaliação'||st==='IGNORADO';\n   return '<article class=\"auto-result '+(st==='Já monitorada'?'already':'')+(st==='IGNORADO'?' ignored':'')+'\"><div class=\"auto-result-main\"><div class=\"auto-result-title\"><span class=\"tag\">'+esc(x.fonte)+'</span><span class=\"tag\">'+esc(categoriaAutoLabel(x))+'</span></div><h4>'+esc((x.tipo||'')+' '+(x.numero||'')+'/'+(x.ano||''))+'</h4><p>'+esc(x.ementa||x.titulo||'Ementa não informada')+'</p>'+(x.autor?'<small>Autor: '+esc(x.autor)+'</small>':'')+(x.termos&&x.termos.length?'<div class=\"auto-terms\"><b>Correspondência da busca:</b> '+x.termos.map(function(t){return '<span class=\\\"tag\\\">'+esc(t)+'</span>'}).join(' ')+'</div>':'<div class=\"auto-terms muted\"><b>Correspondência da busca:</b> não informada pela fonte</div>')+'</div><div class=\"auto-result-side\">'+(st==='Já monitorada'?'<span class=\"source-status done\">Já monitorada</span>':st==='Em avaliação'?'<span class=\"source-status pending\">Em avaliação</span>':st==='IGNORADO'?'<span class=\"muted\">Ignorada</span>':'<span class=\"source-status done\">Nova</span>')+(x.link?'<a class=\"secondary link-btn\" target=\"_blank\" href=\"'+esc(x.link)+'\">Ver fonte oficial</a>':'')+(!blocked?'<button class=\"primary\" onclick=\"adicionarResultadoAutomatico(\\''+escJs(x.id)+'\\')\">Enviar para avaliação</button><button class=\"secondary\" onclick=\"ignorarResultadoAutomatico(\\''+escJs(x.id)+'\\')\">Ignorar</button>':'')+'</div></article>';\n }).join(''): '<div class=\"empty compact-empty\">Nenhum resultado corresponde aos filtros.</div>';\n}\nfunction renderResultadosAutomaticos(rows,filterKey){\n window.__autoRows=window.__autoRows||{};\n window.__autoRows[filterKey]=rows;\n if(!rows.length)return '<div class=\"empty compact-empty\">Nenhum resultado automático para esta fonte ainda.</div>';\n var categories=[],types=[];\n rows.forEach(function(x){\n   var cat=categoriaAutoLabel(x); if(categories.indexOf(cat)<0)categories.push(cat);\n   var tp=String(x.tipo||'').toUpperCase(); if(tp&&types.indexOf(tp)<0)types.push(tp);\n });\n categories.sort(); types.sort();\n var onchange=\"renderAutomaticRows(window.__autoRows['\"+escJs(filterKey)+\"'],'\"+escJs(filterKey)+\"')\";\n setTimeout(function(){renderAutomaticRows(rows,filterKey)},0);\n return '<div class=\"automatic-filters\"><label>Status<select id=\"'+filterKey+'-status\" onchange=\"'+onchange+'\"><option value=\"todos\">Todos</option><option value=\"Nova\">Novas</option><option value=\"Já monitorada\">Já monitoradas</option><option value=\"Em avaliação\">Em avaliação</option><option value=\"IGNORADO\">Ignoradas</option></select></label><label>Categoria<select id=\"'+filterKey+'-category\" onchange=\"'+onchange+'\"><option value=\"todos\">Todas</option>'+categories.map(function(v){return '<option value=\"'+esc(v)+'\">'+esc(v)+'</option>'}).join('')+'</select></label><label>Sigla<select id=\"'+filterKey+'-type\" onchange=\"'+onchange+'\"><option value=\"todos\">Todas</option>'+types.map(function(v){return '<option value=\"'+esc(v)+'\">'+esc(v)+'</option>'}).join('')+'</select></label><span class=\"automatic-filter-summary\" id=\"'+filterKey+'-summary\"></span></div><div class=\"auto-result-list\" id=\"'+filterKey+'-list\"></div>';\n}\nasync function pesquisarAutomaticamente(fonte,botao){\n try{\n  if(botao){botao.disabled=true;botao.classList.add('is-loading');botao.textContent='Pesquisando...';}\n  var r=await api('buscarNovasPropositurasAutomatica',[token,current?current.id:'',fonte,current?current.responsavel:'']);\n  toast(fonte+': '+Number(r.encontrados||0)+' resultado(s) encontrado(s).');\n  if(current&&current.id) await renderBuscaGuiada(current.id);\n }catch(e){toast(e.message)}finally{if(botao){botao.disabled=false;botao.classList.remove('is-loading')}}\n}\nasync function adicionarResultadoAutomatico(id){\n try{\n  await api('adicionarResultadoPesquisaAutomatica',[token,id,current?current.id:'',current?current.responsavel:'']);\n  invalidate('avaliacao');\n  toast('Propositura enviada para avaliação.');\n  if(current&&current.id) await renderBuscaGuiada(current.id); else await pesquisaDiaria();\n }catch(e){toast(e.message)}\n}\nasync function ignorarResultadoAutomatico(id){\n try{\n  await api('ignorarResultadoPesquisaAutomatica',[token,id]);\n  toast('Resultado ignorado.');\n  if(current&&current.id) await renderBuscaGuiada(current.id); else await pesquisaDiaria();\n }catch(e){toast(e.message)}\n}\nasync function adicionarTermoApoio(){\n var e=document.getElementById('guidedNewTerm'),t=e&&e.value.trim();\n if(!t)return toast('Informe o termo de apoio.');\n try{await api('addTermoPesquisa',[token,t]);toast('Termo incluído.');if(current&&current.id)await renderBuscaGuiada(current.id);}catch(e2){toast(e2.message)}\n}\nasync function removerTermoApoio(id){\n if(!id)return;\n try{await api('removerTermoPesquisa',[token,id]);toast('Termo removido da lista ativa.');if(current&&current.id)await renderBuscaGuiada(current.id);}catch(e){toast(e.message)}\n}\nfunction fonteSafe(s){return String(s||'').replace(/[^a-zA-Z0-9À-ÿ]/g,'').replace(/á|à|ã|â|ä/gi,'a').replace(/é|è|ê|ë/gi,'e').replace(/í|ì|î|ï/gi,'i').replace(/ó|ò|õ|ô|ö/gi,'o').replace(/ú|ù|û|ü/gi,'u').replace(/ç/gi,'c')}\nfunction safeId(s){return semAcentoClient(String(s)).replace(/[^a-zA-Z0-9]/g,'')}\nfunction semAcentoClient(s){return s.normalize?s.normalize('NFD').replace(/[\\u0300-\\u036f]/g,''):s}\nasync function concluirPesquisaCasa(fonte){var q=document.getElementById('qty-'+safeId(fonte));try{await api('salvarBuscaManual',[token,current.id,current.responsavel,fonte,Number(q&&q.value||0)]);toast(fonte+' concluída.');renderBuscaGuiada(current.id);}catch(e){toast(e.message)}}\nasync function reabrirPesquisaCasa(fonte){try{await api('reabrirBuscaManual',[token,current.id,fonte]);toast(fonte+' reaberta.');renderBuscaGuiada(current.id);}catch(e){toast(e.message)}}\nfunction mostrarRevisao(){var x=document.getElementById('reviewArea');if(x)x.innerHTML='<div class=\"after-check review-ready\"><div><b>3 de 3 pesquisas concluídas</b><p>Agora você pode revisar o relatório. A observação será solicitada somente na etapa final.</p></div><button class=\"primary\" onclick=\"revisarRelatorio()\">Revisar relatório diário</button></div>';}\nfunction abrirCadastroCandidata(){renderCadastroCandidata('candidateForm',current?current.id:'',current?current.responsavel:'');}\nfunction fecharCadastroCandidata(){var x=document.getElementById('candidateForm');if(x)x.innerHTML='';}\nfunction renderCadastroCandidata(containerId,verificationId,responsavel){\n var c=document.getElementById(containerId);if(!c)return;\n c.innerHTML='<div class=\"candidate-form\"><h3>Registrar para avaliação</h3><p class=\"form-help\"><b>Antes de enviar:</b> use a casa onde a matéria será acompanhada, copie o link da página oficial e confira tipo, número e ano. O cadastro ainda poderá ser corrigido na etapa de avaliação e só entrará no monitoramento depois de validado.</p><div class=\"candidate-grid\"><label>Casa<select id=\"cfFonte\"><option>Câmara</option><option>Senado</option><option>ALESP</option></select></label><label>Tipo<input id=\"cfTipo\" placeholder=\"Ex.: PL, PLC, REQ\"></label><label>Número<input id=\"cfNumero\" inputmode=\"numeric\" placeholder=\"Somente número\"></label><label>Ano<input id=\"cfAno\" type=\"number\" min=\"1900\" max=\"2100\" placeholder=\"2026\"></label><label class=\"span2\">Link oficial<input id=\"cfLink\" placeholder=\"Cole o link da página oficial da matéria\"></label><label>ID oficial <span class=\"optional\">(opcional)</span><input id=\"cfId\" inputmode=\"numeric\" placeholder=\"O sistema tenta extrair do link\"></label><label class=\"span3\">Ementa / resumo<input id=\"cfEmenta\" placeholder=\"Recomendado para facilitar a avaliação\"></label><label class=\"span3\">Observação interna<input id=\"cfObs\" placeholder=\"Opcional\"></label></div><div class=\"form-actions\"><button class=\"secondary\" onclick=\"fecharCadastroCandidata()\">Cancelar</button><button class=\"primary\" onclick=\"registrarCandidata(\\''+escJs(verificationId||'')+'\\',\\''+escJs(responsavel||'')+'\\')\">Enviar para avaliação</button></div></div>';\n}\nasync function registrarCandidata(verificationId,responsavel){\n var dados={fonte:document.getElementById('cfFonte').value,tipo:document.getElementById('cfTipo').value,numero:document.getElementById('cfNumero').value,ano:document.getElementById('cfAno').value,link:document.getElementById('cfLink').value,idOficial:document.getElementById('cfId').value,ementa:document.getElementById('cfEmenta').value,observacao:document.getElementById('cfObs').value};\n try{\n  var r=await api('registrarCandidataManual',[token,verificationId||'',responsavel||'',dados]);\n  invalidate('avaliacao');\n  var f=document.getElementById('candidateForm');if(f)f.innerHTML='';\n  toast(r.problemas&&r.problemas.length?'Registrada para avaliação. Há campos para revisar antes da aprovação.':'Propositura enviada para avaliação.');\n }catch(e){toast(e.message)}\n}\n\nasync function pesquisaDiaria(){\n setTitle('Pesquisa diária','Pesquisa automática de novas proposituras e inclusão para avaliação');\n try{\n  var d=await api('getPesquisaDiaria',[token]);\n  var results=await Promise.all(d.fontes.map(async function(f){try{return {fonte:f.fonte,link:f.link,resultados:await api('getResultadosPesquisaAutomatica',[token,'',f.fonte])}}catch(_){return {fonte:f.fonte,link:f.link,resultados:[]}}}));\n  page().innerHTML='<div class=\"panel\"><div class=\"panel-head\"><div><h2>Pesquisa diária</h2><p class=\"intro\">Execute a pesquisa automática pelos Termos de apoio. O sistema consulta as fontes oficiais e traz as matérias encontradas para sua decisão.</p></div></div>'+\n   '<details class=\"terms terms-managed\" open><summary>Termos de apoio</summary><div class=\"term-chips\">'+d.palavras.map(function(w){return '<span class=\"term-chip\">'+esc(w.termo)+' <button title=\"Remover termo\" onclick=\"removerTermo(\\''+escJs(w.id)+'\\')\">×</button></span>'}).join('')+'</div><div class=\"term-add\"><input id=\"novoTermo\" placeholder=\"Adicionar novo termo de apoio\" onkeydown=\"if(event.key===\\'Enter\\')adicionarTermo()\"><button class=\"secondary\" onclick=\"adicionarTermo()\">+ Incluir termo</button></div><p class=\"terms-help\">Os termos ativos alimentam as pesquisas automáticas da Câmara, Senado e ALESP.</p></details>'+\n   '<div class=\"automatic-source-list\">'+results.map(function(f){return '<section class=\"automatic-source-panel\"><div class=\"automatic-source-head\"><div><h3>'+esc(f.fonte)+'</h3><p>Pesquisa automática pelos termos ativos.</p></div><div class=\"source-action-row\"><button class=\"primary\" onclick=\"pesquisarAutomaticamenteStandalone(\\''+escJs(f.fonte)+'\\',this)\">'+(f.resultados.length?'Pesquisar novamente':'Pesquisar automaticamente')+'</button><a class=\"secondary link-btn\" target=\"_blank\" href=\"'+esc(f.link)+'\">Abrir fonte oficial</a></div></div><div class=\"automatic-results\">'+renderResultadosAutomaticos(f.resultados,'daily_'+safeId(fonteSafe(f.fonte)))+'</div></section>'}).join('')+'</div>'+\n   '<div class=\"standalone-register\"><div class=\"section-title-row\"><div><h3>Encontrou uma matéria fora da pesquisa?</h3><p>Você também pode registrá-la manualmente para avaliação.</p></div></div><button class=\"primary\" onclick=\"renderCadastroCandidata(\\'candidateForm\\',\\'\\',\\'\\')\">+ Registrar para avaliação</button><div id=\"candidateForm\"></div></div></div>';\n }catch(e){toast(e.message)}\n}\nasync function pesquisarAutomaticamenteStandalone(fonte,botao){\n try{\n  if(botao){botao.disabled=true;botao.classList.add('is-loading');botao.textContent='Pesquisando...';}\n  var r=await api('buscarNovasPropositurasAutomatica',[token,'',fonte,'']);\n  toast(fonte+': '+Number(r.encontrados||0)+' resultado(s) encontrado(s).');\n  await pesquisaDiaria();\n }catch(e){toast(e.message)}finally{if(botao){botao.disabled=false;botao.classList.remove('is-loading')}}\n}\nasync function adicionarTermo(){var t=document.getElementById('novoTermo').value.trim();if(!t)return toast('Informe o novo termo.');try{await api('addTermoPesquisa',[token,t]);toast('Termo incluído.');pesquisaDiaria();}catch(e){toast(e.message)}}\nasync function removerTermo(id){try{await api('removerTermoPesquisa',[token,id]);toast('Termo removido da lista ativa.');pesquisaDiaria();}catch(e){toast(e.message)}}\n\nasync function revisarRelatorio(){try{var r=await api('prepararRelatorio',[token,current.id]);renderRelatorio(r,false)}catch(e){toast(e.message)}}\nfunction renderRelatorio(r,salvo){setTitle('Relatório diário','Revisão e registro da verificação');var d=r.detalhes||{},rows=d.resultados||[],a=Number(r.alteracoes||0),manual=(r.buscasManuais||[]),found=manual.reduce(function(x,y){return x+Number(y.resultadosEncontrados||0)},0);page().innerHTML='<div class=\"report\"><div class=\"report-head\"><div><span class=\"eyebrow\">RELATÓRIO DIÁRIO</span><h2>Monitoramento Legislativo</h2><p>Corpo de Bombeiros</p></div></div><div class=\"report-meta compact\"><div><small>Responsável</small><b>'+esc(r.responsavel)+'</b></div><div><small>Conclusão</small><b>'+esc(r.emissao||r.fimTecnico)+'</b></div></div><section><h3>Proposituras monitoradas</h3><p>Foram verificadas <b>'+r.totalVerificado+' de '+r.totalPrevisto+' proposituras cadastradas</b>.</p><div class=\"sources\">'+rows.map(function(x){return '<div class=\"source-box\"><small>'+esc(x.fonte)+'</small><b>'+Number(x.verificado||0)+' de '+Number(x.previsto||0)+'</b></div>'}).join('')+'</div><p class=\"result '+(a?'attn':'good')+'\">'+(a?'Foram identificadas '+a+' alteração(ões) nas matérias monitoradas.':'Não foram identificadas alterações nas matérias monitoradas.')+'</p></section><section><h3>Pesquisa de novas proposituras</h3><p>A pesquisa guiada foi registrada nas três casas legislativas.</p><div class=\"sources\">'+manual.map(function(x){return '<div class=\"source-box\"><small>'+esc(x.fonte)+'</small><b>'+Number(x.resultadosEncontrados||0)+' encontrada(s)</b></div>'}).join('')+'</div><p class=\"result '+(found?'attn':'good')+'\">'+(found?'Foram informadas '+found+' possível(is) nova(s) matéria(s). As cadastradas ficam em Avaliação de proposituras.':'Não foram informadas novas proposituras relevantes.')+'</p></section><section><h3>Observação do responsável</h3>'+(salvo?'<div class=\"obsbox\"><p>'+esc(r.observacao)+'</p></div><div class=\"report-bottom no-print\"><button class=\"primary report-print-btn\" onclick=\"window.print()\">Imprimir / Salvar PDF</button><button class=\"secondary\" onclick=\"painel()\">Voltar ao painel</button></div>':'<div class=\"obsbox\"><textarea id=\"obs\" placeholder=\"Registre sua observação após analisar o relatório\"></textarea></div><div class=\"report-actions no-print\"><button class=\"secondary\" onclick=\"renderBuscaGuiada(current.id)\">Voltar</button><button class=\"primary\" onclick=\"salvarRelatorio()\">Salvar relatório diário</button></div>')+'</section></div>';}\nasync function salvarRelatorio(){var obs=document.getElementById('obs').value.trim();if(!obs)return toast('Informe a observação.');try{var r=await api('salvarRelatorio',[token,current.id,obs]);dash=await api('getDashboard',[token]);invalidate('relatorios');renderRelatorio(r,true);toast('Relatório salvo.')}catch(e){toast(e.message)}}\nasync function proposituras(){setTitle('Proposituras','Base atualmente monitorada');try{var rows=await cached('proposituras','getProposituras',[token],45000);page().innerHTML='<div class=\"panel\"><div class=\"panel-head\"><div><h2>Proposituras monitoradas</h2><p class=\"intro\">Matérias incluídas no acompanhamento automático.</p></div><button class=\"secondary\" onclick=\"atualizarRegimesAlespUI(this)\">↻ Atualizar regimes ALESP</button></div><div class=\"toolbar\"><input id=\"q\" placeholder=\"Buscar número, autor ou ementa\"><select id=\"f\"><option value=\"\">Todas as casas</option><option>Câmara</option><option>Senado</option><option>ALESP</option></select></div><div id=\"propTable\"></div></div>';function draw(){var q=document.getElementById('q').value.toLowerCase(),f=document.getElementById('f').value,a=rows.filter(function(x){return(!f||x.fonte===f)&&(!q||(x.tipo+' '+x.numero+' '+x.ano+' '+x.autor+' '+x.ementa).toLowerCase().indexOf(q)>=0)});document.getElementById('propTable').innerHTML=tableProps(a)}document.getElementById('q').oninput=draw;document.getElementById('f').onchange=draw;draw();}catch(e){toast(e.message)}}\nasync function atualizarRegimesAlespUI(btn){\n var original=btn?btn.textContent:'';\n try{\n  if(btn){btn.disabled=true;btn.textContent='Iniciando atualização...';btn.classList.add('is-loading')}\n  toast('Enviando regimes da ALESP para processamento...');\n  var job=await api('atualizarRegimesAlesp',[token]);\n  var requestId=job.requestId;\n  var inicio=Date.now();\n  while(Date.now()-inicio<180000){\n    if(btn)btn.textContent='Processando regimes ALESP...';\n    await new Promise(function(resolve){setTimeout(resolve,3500)});\n    var s=await api('getStatusAtualizacaoRegimesAlesp',[token,requestId]);\n    if(String(s.status)==='CONCLUIDO'){\n      invalidate('proposituras');\n      toast('Regimes ALESP: '+Number(s.localizados||0)+' de '+Number(s.previstos||0)+' localizados; '+Number(s.atualizados||0)+' atualizado(s).');\n      await proposituras();\n      return;\n    }\n    if(String(s.status)==='ERRO') throw new Error(s.erro||'Falha no processamento dos regimes ALESP.');\n  }\n  throw new Error('O processamento ainda não terminou. Tente atualizar a tela em alguns instantes.');\n }catch(e){toast(e.message)}\n finally{\n  if(btn&&document.body.contains(btn)){btn.disabled=false;btn.textContent=original||'↻ Atualizar regimes ALESP';btn.classList.remove('is-loading')}\n }\n}\nfunction separarMovimentoLegado(txt){\n var s=String(txt||'').trim(),m=s.match(/^(\\d{2}\\/\\d{2}\\/\\d{4})\\s*[-–—]\\s*(.+)$/);\n return m?{data:m[1],texto:m[2]}:{data:'',texto:s};\n}\nfunction tableProps(a){\n if(!a.length)return '<div class=\"empty\">Nenhum registro.</div>';\n return '<div class=\"table-wrap\"><table class=\"props-table\"><colgroup><col class=\"col-house\"><col class=\"col-prop\"><col class=\"col-status\"><col class=\"col-move\"><col class=\"col-date\"><col class=\"col-source\"></colgroup><thead><tr><th>Casa</th><th>Propositura</th><th>Situação / Regime</th><th>Última movimentação</th><th>Data</th><th>Fonte</th></tr></thead><tbody>'+a.map(function(x){\n  var isA=x.fonte==='ALESP',erro=String(x.erroUltimaConsulta||'').trim();\n  var sit=isA?(x.regimeTramitacao||'Aguardando atualização do regime'):(x.situacaoAtual||'Aguardando calibração');\n  var sitLabel=isA?'Regime de tramitação':'Situação atual';\n  var mov=x.tramitacaoAtual||'',data=x.dataUltimaTramitacao||'',fallback=false;\n  if(!mov&&isA&&x.andamento){var leg=separarMovimentoLegado(x.andamento);mov=leg.texto;data=data||leg.data;fallback=true}\n  if(!mov)mov=erro?'Consulta com pendência':(isA?'Sem movimentação recente detectada':'Aguardando calibração');\n  if(!data)data='—';\n  return '<tr><td><span class=\"tag\">'+esc(x.fonte)+'</span></td><td class=\"prop-main\"><b class=\"prop-id\">'+esc(x.tipo)+' '+esc(x.numero)+'/'+esc(x.ano)+'</b><div class=\"prop-ementa\">'+esc(short(x.ementa,210))+'</div></td><td><div class=\"status-label\">'+esc(sitLabel)+'</div><div class=\"status-value\">'+esc(short(sit,120))+'</div>'+(isA&&x.dataRegime?'<div class=\"muted\">Desde '+esc(x.dataRegime)+'</div>':'')+'</td><td><div class=\"movement-text\">'+esc(short(mov,220))+'</div>'+(fallback?'<div class=\"data-note\">Último andamento conhecido da base anterior</div>':'')+(x.orgaoAtual?'<div class=\"muted\">Órgão/local: '+esc(x.orgaoAtual)+'</div>':'')+(x.detalheTramitacao?'<div class=\"muted movement-detail\">'+esc(short(x.detalheTramitacao,130))+'</div>':'')+(erro?'<div class=\"query-warning\">Pendência na última consulta: '+esc(short(erro,120))+'</div>':'')+'</td><td>'+esc(data)+'</td><td>'+(x.link?'<a class=\"primary link-btn prop-source-btn\" target=\"_blank\" href=\"'+esc(x.link)+'\">Abrir</a>':'—')+'</td></tr>';\n }).join('')+'</tbody></table></div>';\n}\nasync function alteracoes(){\n setTitle('Alterações','Mudanças detectadas automaticamente e aguardando análise');\n try{\n  var rows=await api('getAlteracoes',[token]);\n  var pend=rows.filter(function(x){return String(x.status||'Pendente')==='Pendente'});\n  var analisadas=rows.filter(function(x){return String(x.status||'Pendente')!=='Pendente'});\n  page().innerHTML=\n   '<div class=\"panel changes-panel\"><div class=\"changes-header\"><div><h2>Alterações pendentes</h2><p class=\"intro\">Confira a mudança na fonte oficial e escolha Confirmar ou Ignorar.</p></div><span class=\"pending-count\">'+pend.length+' pendente(s)</span></div>'+\n   renderAlteracoesPendentes(pend)+\n   '<div class=\"reviewed-section\"><div class=\"changes-header\"><div><h2>Analisadas</h2><p class=\"intro\">Alterações já confirmadas ou ignoradas. É possível reverter uma decisão.</p></div><span class=\"reviewed-count\">'+analisadas.length+' analisada(s)</span></div>'+\n   renderAlteracoesAnalisadas(analisadas)+'</div></div>';\n  document.querySelectorAll('.confirm-change').forEach(function(b){b.onclick=function(){decidirAlteracao(b.dataset.id,'Confirmada')}});\n  document.querySelectorAll('.ignore-change').forEach(function(b){b.onclick=function(){decidirAlteracao(b.dataset.id,'Ignorada')}});\n  document.querySelectorAll('.revert-change').forEach(function(b){b.onclick=function(){reverterAlteracaoUI(b.dataset.id)}});\n }catch(e){toast(e.message)}\n}\n\nfunction renderAlteracoesPendentes(rows){\n if(!rows.length)return '<div class=\"empty compact-empty\">Nenhuma alteração pendente.</div>';\n return '<div class=\"change-list\">'+rows.map(function(x){\n  return '<article class=\"change-card\">'+\n   '<div class=\"change-card-top\"><div><div class=\"change-tags\"><span class=\"tag\">'+esc(x.fonte)+'</span><span class=\"change-type\">'+esc(x.campoLabel||'Alteração')+'</span></div><h3>'+esc(x.propositura)+'</h3><small>Detectada em '+esc(x.data)+'</small></div>'+\n   (x.link?'<a class=\"primary link-btn change-source-btn\" target=\"_blank\" href=\"'+esc(x.link)+'\">Abrir fonte oficial</a>':'<span class=\"muted\">Link não disponível</span>')+\n   '</div>'+\n   '<div class=\"change-comparison\"><div class=\"change-value old\"><small>DE</small><p>'+esc(x.anterior||'—')+'</p></div><div class=\"change-arrow\">→</div><div class=\"change-value new\"><small>PARA</small><p>'+esc(x.novo||'—')+'</p></div></div>'+\n   '<div class=\"change-actions\"><button class=\"secondary ignore-change\" data-id=\"'+esc(x.id)+'\">Ignorar</button><button class=\"primary confirm-change\" data-id=\"'+esc(x.id)+'\">Confirmar alteração</button></div>'+\n   '</article>';\n }).join('')+'</div>';\n}\n\nfunction renderAlteracoesAnalisadas(rows){\n if(!rows.length)return '<div class=\"empty compact-empty\">Nenhuma alteração analisada.</div>';\n return '<div class=\"reviewed-list\">'+rows.map(function(x){\n  var st=String(x.status);\n  return '<article class=\"reviewed-change '+(st==='Confirmada'?'confirmed':'ignored')+'\">'+\n   '<div class=\"reviewed-main\"><div><div class=\"change-tags\"><span class=\"tag\">'+esc(x.fonte)+'</span><span class=\"change-type\">'+esc(x.campoLabel||'Alteração')+'</span><span class=\"decision-badge '+(st==='Confirmada'?'confirmed':'ignored')+'\">'+esc(st)+'</span></div><h3>'+esc(x.propositura)+'</h3><p><b>De:</b> '+esc(short(x.anterior,160))+' <span class=\"inline-arrow\">→</span> <b>Para:</b> '+esc(short(x.novo,160))+'</p><small>Detectada: '+esc(x.data)+(x.analisadoEm?' · Analisada: '+esc(x.analisadoEm):'')+'</small></div>'+\n   '<div class=\"reviewed-actions\">'+(x.link?'<a class=\"secondary link-btn\" target=\"_blank\" href=\"'+esc(x.link)+'\">Fonte oficial</a>':'')+'<button class=\"secondary revert-change\" data-id=\"'+esc(x.id)+'\">Reverter para pendente</button></div></div>'+\n   '</article>';\n }).join('')+'</div>';\n}\n\nasync function decidirAlteracao(id,status){\n try{\n  await api('setAlteracaoStatus',[token,id,status]);\n  toast(status==='Confirmada'?'Alteração confirmada.':'Alteração ignorada.');\n  await alteracoes();\n }catch(e){toast(e.message)}\n}\nasync function reverterAlteracaoUI(id){\n try{\n  await api('reverterAlteracao',[token,id]);\n  toast('Alteração voltou para Pendentes.');\n  await alteracoes();\n }catch(e){toast(e.message)}\n}\n\nasync function avaliacao(){setTitle('Avaliação de proposituras','Revisão dos dados antes de entrar no monitoramento automático');try{var rows=await cached('avaliacao','getCandidatasPendentes',[token],15000);page().innerHTML='<div class=\"panel\"><h2>Aguardando avaliação</h2><p class=\"intro\">Nenhuma matéria entra no monitoramento apenas por ter sido cadastrada. Revise e corrija os dados abaixo; a aprovação só é liberada quando as informações mínimas estão consistentes.</p>'+tableAval(rows)+'</div>';bindAvaliacao()}catch(e){toast(e.message)}}\nfunction tableAval(a){if(!a.length)return '<div class=\"empty\">Nenhuma propositura aguardando avaliação.</div>';return '<div class=\"evaluation-list\">'+a.map(function(x){var problems=String(x.problemas||'').trim();return '<div class=\"evaluation-card\" id=\"card-'+esc(x.id)+'\"><div class=\"evaluation-main\"><div><span class=\"tag\">'+esc(x.fonte)+'</span><h3>'+esc(x.tipo)+' '+esc(x.numero)+'/'+esc(x.ano)+'</h3><p>'+esc(x.ementa||'Ementa não informada')+'</p><small>Registrada por '+esc(x.responsavel||'—')+' · '+esc(x.data)+'</small></div><a class=\"primary link-btn evaluation-source-btn\" target=\"_blank\" href=\"'+esc(x.link)+'\">Abrir fonte oficial</a></div>'+(problems?'<div class=\"candidate-warning\"><b>Revisar antes de aprovar:</b> '+esc(problems)+'</div>':'<div class=\"candidate-ready\">Dados básicos consistentes. Confira a fonte oficial antes de aprovar.</div>')+'<div class=\"evaluation-actions\"><button class=\"secondary btn-editar\" data-id=\"'+esc(x.id)+'\">Editar / corrigir</button><button class=\"secondary btn-validar\" data-id=\"'+esc(x.id)+'\">Validar dados</button><button class=\"secondary danger btn-ignorar\" data-id=\"'+esc(x.id)+'\">Ignorar</button><button class=\"primary btn-aprovar\" data-id=\"'+esc(x.id)+'\">Adicionar ao monitoramento</button></div><div class=\"edit-host\" id=\"edit-'+esc(x.id)+'\"></div></div>'}).join('')+'</div>'}\nfunction bindAvaliacao(){document.querySelectorAll('.btn-editar').forEach(function(b){b.onclick=function(){editarCandidata(b.dataset.id)}});document.querySelectorAll('.btn-validar').forEach(function(b){b.onclick=function(){validarCandidataUI(b.dataset.id)}});document.querySelectorAll('.btn-aprovar').forEach(function(b){b.onclick=function(){aprovar(b.dataset.id)}});document.querySelectorAll('.btn-ignorar').forEach(function(b){b.onclick=function(){ignorar(b.dataset.id)}})}\nasync function editarCandidata(id){\n try{\n  var rows=await api('getCandidatasPendentes',[token]),x=rows.find(function(r){return String(r.id)===String(id)});if(!x)return toast('Registro não encontrado.');\n  var h=document.getElementById('edit-'+id);\n  h.innerHTML='<div class=\"candidate-edit\"><h4>Corrigir dados</h4><div class=\"candidate-grid\"><label>Casa<select id=\"efFonte-'+id+'\"><option '+(x.fonte==='Câmara'?'selected':'')+'>Câmara</option><option '+(x.fonte==='Senado'?'selected':'')+'>Senado</option><option '+(x.fonte==='ALESP'?'selected':'')+'>ALESP</option></select></label><label>Tipo<input id=\"efTipo-'+id+'\" value=\"'+esc(x.tipo)+'\"></label><label>Número<input id=\"efNumero-'+id+'\" value=\"'+esc(x.numero)+'\"></label><label>Ano<input id=\"efAno-'+id+'\" value=\"'+esc(x.ano)+'\"></label><label class=\"span2\">Link oficial<input id=\"efLink-'+id+'\" value=\"'+esc(x.link)+'\"></label><label>ID oficial<input id=\"efId-'+id+'\" value=\"'+esc(x.idOficial||'')+'\"></label><label class=\"span3\">Ementa / resumo<input id=\"efEmenta-'+id+'\" value=\"'+esc(x.ementa||'')+'\"></label><label class=\"span3\">Observação interna<input id=\"efObs-'+id+'\" value=\"'+esc(x.observacao||'')+'\"></label></div><div class=\"form-actions\"><button class=\"secondary\" onclick=\"document.getElementById(\\'edit-'+id+'\\').innerHTML=\\'\\'\">Cancelar</button><button class=\"primary\" onclick=\"salvarEdicaoCandidata(\\''+escJs(id)+'\\')\">Salvar correções</button></div></div>';\n }catch(e){toast(e.message)}\n}\nasync function salvarEdicaoCandidata(id){var dados={fonte:document.getElementById('efFonte-'+id).value,tipo:document.getElementById('efTipo-'+id).value,numero:document.getElementById('efNumero-'+id).value,ano:document.getElementById('efAno-'+id).value,link:document.getElementById('efLink-'+id).value,idOficial:document.getElementById('efId-'+id).value,ementa:document.getElementById('efEmenta-'+id).value,observacao:document.getElementById('efObs-'+id).value};try{var r=await api('atualizarCandidata',[token,id,dados]);invalidate('avaliacao');toast(r.problemas&&r.problemas.length?'Correções salvas. Ainda existem itens para revisar.':'Correções salvas.');avaliacao()}catch(e){toast(e.message)}}\nasync function validarCandidataUI(id){try{var r=await api('validarCandidataParaAprovacao',[token,id]);invalidate('avaliacao');if(r.ok)toast('Dados validados. Confira visualmente a fonte oficial e, estando correto, adicione ao monitoramento.');else toast('Ainda há dados para corrigir: '+r.problemas.join(' | '));avaliacao()}catch(e){toast(e.message)}}\nasync function aprovar(id){try{await api('aprovarCandidata',[token,id]);invalidate('avaliacao','proposituras');dash=await api('getDashboard',[token]);toast('Propositura adicionada ao monitoramento.');avaliacao()}catch(e){toast(e.message)}}\nasync function ignorar(id){try{await api('ignorarCandidata',[token,id]);invalidate('avaliacao');toast('Propositura ignorada.');avaliacao()}catch(e){toast(e.message)}}\n\n\nasync function configuracoes(){\n setTitle('Configurações','Preferências e acesso ao Monitor Legislativo');\n page().innerHTML='<div class=\"panel settings-panel\"><h2>Configurações</h2><div class=\"settings-section\"><h3>Senha de acesso</h3><p class=\"intro\">A alteração vale para todos que usam a senha compartilhada. Ao salvar, as sessões abertas serão encerradas e será necessário entrar novamente.</p><div class=\"password-grid\"><label>Senha atual<input id=\"senhaAtual\" type=\"password\" autocomplete=\"current-password\"></label><label>Nova senha<input id=\"novaSenha\" type=\"password\" autocomplete=\"new-password\" placeholder=\"Mínimo de 6 caracteres\"></label><label>Confirmar nova senha<input id=\"confSenha\" type=\"password\" autocomplete=\"new-password\"></label></div><div class=\"form-actions\"><button class=\"primary\" onclick=\"salvarNovaSenha()\">Alterar senha</button></div></div><div class=\"settings-section\"><h3>Endereço do sistema</h3><p class=\"intro\">O endereço longo do Google continua sendo o endereço técnico. Um domínio curto pode redirecionar para ele sem alterar o funcionamento do monitor.</p><div class=\"address-example\">Exemplo: <b>monitorbombeiros.com.br</b> → endereço do Apps Script</div></div></div>';\n}\nasync function salvarNovaSenha(){\n var atual=document.getElementById('senhaAtual').value,nova=document.getElementById('novaSenha').value,conf=document.getElementById('confSenha').value;\n try{\n  var r=await api('alterarSenhaAcesso',[token,atual,nova,conf]);\n  localStorage.removeItem('ml_token');token='';\n  mostrarLogin(r.message||'Senha alterada. Entre novamente.');\n }catch(e){toast(e.message)}\n}\n\nasync function relatorios(){\n setTitle('Relatórios','Histórico dos relatórios diários');\n try{\n  var rs=await cached('relatorios','getRelatorios',[token],30000);\n  page().innerHTML='<div class=\"panel\"><h2>Relatórios salvos</h2><p class=\"intro\">Abra um relatório para consultar, imprimir ou salvar novamente em PDF.</p>'+(rs.length?'<div class=\"table-wrap\"><table><thead><tr><th>Relatório</th><th>Responsável</th><th>Verificadas</th><th>Alterações</th><th>Conclusão</th></tr></thead><tbody>'+rs.map(function(x){return '<tr><td><button class=\"primary report-open-btn\" onclick=\"abrirRelatorioSalvo(\\''+escJs(x.id)+'\\')\">Abrir relatório</button></td><td>'+esc(x.responsavel)+'</td><td>'+x.totalVerificado+'/'+x.totalPrevisto+'</td><td>'+x.alteracoes+'</td><td>'+esc(x.emissao||x.fimTecnico||'—')+'</td></tr>'}).join('')+'</tbody></table></div>':'<div class=\"empty\">Nenhum relatório salvo.</div>')+'</div>';\n }catch(e){toast(e.message)}\n}\nasync function abrirRelatorioSalvo(id){\n try{\n  var r=await api('getRelatorioSalvo',[token,id]);\n  renderRelatorio(r,true);\n  var rep=document.querySelector('.report');\n  if(rep){\n    var back=document.createElement('div');\n    back.className='saved-report-back no-print';\n    back.innerHTML='<button class=\"secondary\" onclick=\"relatorios()\">← Voltar aos relatórios</button>';\n    rep.insertBefore(back,rep.firstChild);\n  }\n }catch(e){toast(e.message)}\n}\n\nfunction opts(a,v){return a.map(function(x){return '<option '+(String(x)===String(v)?'selected':'')+'>'+x+'</option>'}).join('')}function short(s,n){s=String(s||'');return s.length>n?s.slice(0,n)+'…':s}function toast(t){var e=document.getElementById('toast');e.textContent=t;e.classList.add('show');setTimeout(function(){e.classList.remove('show')},4000)}function esc(s){return String(s==null?'':s).replace(/[&<>\"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]})}function fmtDate(s){var m=String(s||'').match(/(\\d{4})-(\\d{2})-(\\d{2})/);return m?m[3]+'/'+m[2]+'/'+m[1]:String(s||'')}function escJs(s){return String(s==null?'':s).replace(/\\\\/g,'\\\\\\\\').replace(/'/g,\"\\\\'\").replace(/\\r?\\n/g,' ')}\nif(token)mostrar();else mostrarLogin('');\n";

export default function LegacyMonitorPage() {
  useEffect(() => {
    if (typeof window === "undefined") return;
    const marker = "__monitorLegislativoLegacyLoaded";
    if ((window as unknown as Record<string, unknown>)[marker]) return;

    const script = document.createElement("script");
    script.type = "text/javascript";
    script.text = legacyScript;
    document.body.appendChild(script);
    (window as unknown as Record<string, unknown>)[marker] = true;

    return () => {
      script.remove();
      delete (window as unknown as Record<string, unknown>)[marker];
    };
  }, []);

  return <div dangerouslySetInnerHTML={{ __html: initialMarkup }} />;
}
